From 8bac1290c1551bba0c291b2d2b99b061708eb803 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:35:01 +0100
Subject: [PATCH] applets/appmenu: only provide the global menu on the activity
 it is on

A Global Menu widget on one activity's desktop made apps started on any
other activity hide their menubar, leaving them with no menu at all. The
applet now only registers the menu view while it is on the current one.

BUG: 412923
---
 applets/appmenu/CMakeLists.txt    |  1 +
 applets/appmenu/appmenuapplet.cpp | 65 +++++++++++++++++++------------
 applets/appmenu/appmenuapplet.h   | 10 ++++-
 3 files changed, 51 insertions(+), 25 deletions(-)

diff --git a/applets/appmenu/CMakeLists.txt b/applets/appmenu/CMakeLists.txt
index afc2651059..e8d246573a 100644
--- a/applets/appmenu/CMakeLists.txt
+++ b/applets/appmenu/CMakeLists.txt
@@ -20,6 +20,7 @@ target_link_libraries(org.kde.plasma.appmenu PRIVATE
     Qt::Quick
     Qt::DBus
     Plasma::Plasma
+    Plasma::Activities
     KF6::WindowSystem
     KF6::I18n
     PW::LibTaskManager
diff --git a/applets/appmenu/appmenuapplet.cpp b/applets/appmenu/appmenuapplet.cpp
index 79c29a7e32..6cd19b8a93 100644
--- a/applets/appmenu/appmenuapplet.cpp
+++ b/applets/appmenu/appmenuapplet.cpp
@@ -18,7 +18,10 @@
 #include <QScreen>
 #include <QTimer>

-int AppMenuApplet::s_refs = 0;
+#include <Plasma/Containment>
+#include <PlasmaActivities/Consumer>
+
+QSet<AppMenuApplet *> AppMenuApplet::s_activeApplets;
 namespace
 {
 QString viewService()
@@ -29,14 +32,8 @@ QString viewService()

 AppMenuApplet::AppMenuApplet(QObject *parent, const KPluginMetaData &data, const QVariantList &args)
     : Plasma::Applet(parent, data, args)
+    , m_activityConsumer(new KActivities::Consumer(this))
 {
-    ++s_refs;
-    // if we're the first, register the service
-    if (s_refs == 1) {
-        QDBusConnection::sessionBus().interface()->registerService(viewService(),
-                                                                   QDBusConnectionInterface::QueueService,
-                                                                   QDBusConnectionInterface::DontAllowReplacement);
-    }
     /*it registers or unregisters the service when the destroyed value of the applet change,
       and not in the dtor, because:
       when we "delete" an applet, it just hides it for about a minute setting its status
@@ -44,27 +41,47 @@ AppMenuApplet::AppMenuApplet(QObject *parent, const KPluginMetaData &data, const
       another destroyedchanged and destroyed will be false.
       When this happens, if we are the only appmenu applet existing, the dbus interface
       will have to be registered again*/
-    connect(this, &Applet::destroyedChanged, this, [](bool destroyed) {
-        if (destroyed) {
-            // if we were the last, unregister
-            if (--s_refs == 0) {
-                QDBusConnection::sessionBus().interface()->unregisterService(viewService());
-            }
-        } else {
-            // if we're the first, register the service
-            if (++s_refs == 1) {
-                QDBusConnection::sessionBus().interface()->registerService(viewService(),
-                                                                           QDBusConnectionInterface::QueueService,
-                                                                           QDBusConnectionInterface::DontAllowReplacement);
-            }
-        }
-    });
+    connect(this, &Applet::destroyedChanged, this, &AppMenuApplet::updateViewService);
+    // Applications started while the service is registered hide their own menubar,
+    // so only register it while an applet is on the current activity
+    connect(m_activityConsumer, &KActivities::Consumer::currentActivityChanged, this, &AppMenuApplet::updateViewService);
 }

-AppMenuApplet::~AppMenuApplet() = default;
+AppMenuApplet::~AppMenuApplet()
+{
+    if (s_activeApplets.remove(this) && s_activeApplets.isEmpty()) {
+        QDBusConnection::sessionBus().interface()->unregisterService(viewService());
+    }
+}

 void AppMenuApplet::init()
 {
+    if (Plasma::Containment *c = containment()) {
+        connect(c, &Plasma::Containment::activityChanged, this, &AppMenuApplet::updateViewService);
+    }
+    updateViewService();
+}
+
+void AppMenuApplet::updateViewService()
+{
+    const QString activity = containment() ? containment()->activity() : QString();
+    const QString currentActivity = m_activityConsumer->currentActivity();
+    const bool active = !destroyed() && (activity.isEmpty() || currentActivity.isEmpty() || activity == currentActivity);
+
+    const bool wasRegistered = !s_activeApplets.isEmpty();
+    if (active) {
+        s_activeApplets.insert(this);
+    } else {
+        s_activeApplets.remove(this);
+    }
+
+    if (!wasRegistered && !s_activeApplets.isEmpty()) {
+        QDBusConnection::sessionBus().interface()->registerService(viewService(),
+                                                                   QDBusConnectionInterface::QueueService,
+                                                                   QDBusConnectionInterface::DontAllowReplacement);
+    } else if (wasRegistered && s_activeApplets.isEmpty()) {
+        QDBusConnection::sessionBus().interface()->unregisterService(viewService());
+    }
 }

 QAbstractItemModel *AppMenuApplet::model() const
